import {
  boolean,
  index,
  integer,
  text,
  timestamp,
  uniqueIndex,
} from "drizzle-orm/pg-core";

import { session, user } from "../auth";
import { jsonb } from "../jsonb";
import { privateSchema } from "./party-private";

/**
 * Better Auth's OAuth provider (`@better-auth/mcp`) and JWT signing keys, for
 * assistants that connect a volunteer's account (assistants.md). Generated by
 * `auth generate` for Better Auth 1.7; keep the columns in step with the
 * installed version. Server only: rows hold token and client-secret hashes
 * and the private signing key.
 */

export const jwks = privateSchema.table("jwks", {
  alg: text("alg"),
  createdAt: timestamp("created_at").notNull(),
  crv: text("crv"),
  expiresAt: timestamp("expires_at"),
  id: text("id").primaryKey(),
  privateKey: text("private_key").notNull(),
  publicKey: text("public_key").notNull(),
});

export const oauthClient = privateSchema.table(
  "oauth_client",
  {
    applicationType: text("application_type"),
    backchannelLogoutSessionRequired: boolean(
      "backchannel_logout_session_required"
    ),
    backchannelLogoutUri: text("backchannel_logout_uri"),
    clientCredentialsScopes: text("client_credentials_scopes")
      .array()
      .default([]),
    clientDiscoveryId: text("client_discovery_id"),
    clientId: text("client_id").notNull().unique(),
    clientSecret: text("client_secret"),
    contacts: text("contacts").array(),
    createdAt: timestamp("created_at"),
    disabled: boolean("disabled").default(false),
    dpopBoundAccessTokens: boolean("dpop_bound_access_tokens").default(false),
    enableEndSession: boolean("enable_end_session"),
    grantTypes: text("grant_types").array(),
    icon: text("icon"),
    id: text("id").primaryKey(),
    jwks: text("jwks"),
    jwksUri: text("jwks_uri"),
    metadata: jsonb("metadata"),
    name: text("name"),
    policy: text("policy"),
    postLogoutRedirectUris: text("post_logout_redirect_uris").array(),
    redirectUris: text("redirect_uris").array().notNull(),
    referenceId: text("reference_id"),
    requirePKCE: boolean("require_pkce"),
    responseTypes: text("response_types").array(),
    scopes: text("scopes").array(),
    skipConsent: boolean("skip_consent"),
    softwareId: text("software_id"),
    softwareStatement: text("software_statement"),
    softwareVersion: text("software_version"),
    subjectType: text("subject_type"),
    tokenEndpointAuthMethod: text("token_endpoint_auth_method"),
    tos: text("tos"),
    updatedAt: timestamp("updated_at"),
    uri: text("uri"),
    userId: text("user_id").references(() => user.id, { onDelete: "cascade" }),
  },
  (table) => [index("oauth_client_user_id_idx").on(table.userId)]
);

export const oauthResource = privateSchema.table("oauth_resource", {
  accessTokenTtl: integer("access_token_ttl"),
  allowedScopes: text("allowed_scopes").array(),
  createdAt: timestamp("created_at"),
  customClaims: jsonb("custom_claims"),
  disabled: boolean("disabled").default(false),
  dpopBoundAccessTokensRequired: boolean(
    "dpop_bound_access_tokens_required"
  ).default(false),
  id: text("id").primaryKey(),
  identifier: text("identifier").notNull().unique(),
  metadata: jsonb("metadata"),
  name: text("name").notNull(),
  policyVersion: integer("policy_version").default(1),
  refreshTokenTtl: integer("refresh_token_ttl"),
  signingAlgorithm: text("signing_algorithm"),
  signingKeyId: text("signing_key_id"),
  updatedAt: timestamp("updated_at"),
});

export const oauthClientResource = privateSchema.table(
  "oauth_client_resource",
  {
    clientId: text("client_id")
      .notNull()
      .references(() => oauthClient.clientId, { onDelete: "cascade" }),
    createdAt: timestamp("created_at"),
    id: text("id").primaryKey(),
    metadata: jsonb("metadata"),
    resourceId: text("resource_id")
      .notNull()
      .references(() => oauthResource.identifier, { onDelete: "cascade" }),
  },
  (table) => [
    uniqueIndex("oauth_client_resource_client_resource_uidx").on(
      table.clientId,
      table.resourceId
    ),
    index("oauth_client_resource_resource_id_idx").on(table.resourceId),
  ]
);

export const oauthRefreshToken = privateSchema.table(
  "oauth_refresh_token",
  {
    authorizationCodeId: text("authorization_code_id"),
    authTime: timestamp("auth_time"),
    clientId: text("client_id")
      .notNull()
      .references(() => oauthClient.clientId, { onDelete: "cascade" }),
    confirmation: jsonb("confirmation"),
    createdAt: timestamp("created_at").notNull(),
    expiresAt: timestamp("expires_at").notNull(),
    id: text("id").primaryKey(),
    referenceId: text("reference_id"),
    requestedUserInfoClaims: text("requested_user_info_claims").array(),
    resources: text("resources").array(),
    revoked: timestamp("revoked"),
    rotatedAt: timestamp("rotated_at"),
    rotationReplayExpiresAt: timestamp("rotation_replay_expires_at"),
    rotationReplayResponse: text("rotation_replay_response"),
    scopes: text("scopes").array().notNull(),
    sessionId: text("session_id").references(() => session.id, {
      onDelete: "set null",
    }),
    token: text("token").notNull().unique(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
  },
  (table) => [
    index("oauth_refresh_token_client_id_idx").on(table.clientId),
    index("oauth_refresh_token_session_id_idx").on(table.sessionId),
    index("oauth_refresh_token_user_id_idx").on(table.userId),
    index("oauth_refresh_token_authorization_code_id_idx").on(
      table.authorizationCodeId
    ),
  ]
);

export const oauthAccessToken = privateSchema.table(
  "oauth_access_token",
  {
    authorizationCodeId: text("authorization_code_id"),
    clientId: text("client_id")
      .notNull()
      .references(() => oauthClient.clientId, { onDelete: "cascade" }),
    confirmation: jsonb("confirmation"),
    createdAt: timestamp("created_at").notNull(),
    expiresAt: timestamp("expires_at").notNull(),
    id: text("id").primaryKey(),
    referenceId: text("reference_id"),
    refreshId: text("refresh_id").references(() => oauthRefreshToken.id, {
      onDelete: "cascade",
    }),
    requestedUserInfoClaims: text("requested_user_info_claims").array(),
    resources: text("resources").array(),
    revoked: timestamp("revoked"),
    scopes: text("scopes").array().notNull(),
    sessionId: text("session_id").references(() => session.id, {
      onDelete: "set null",
    }),
    token: text("token").notNull().unique(),
    userId: text("user_id").references(() => user.id, { onDelete: "cascade" }),
  },
  (table) => [
    index("oauth_access_token_client_id_idx").on(table.clientId),
    index("oauth_access_token_session_id_idx").on(table.sessionId),
    index("oauth_access_token_user_id_idx").on(table.userId),
    index("oauth_access_token_authorization_code_id_idx").on(
      table.authorizationCodeId
    ),
    index("oauth_access_token_refresh_id_idx").on(table.refreshId),
  ]
);

export const oauthConsent = privateSchema.table(
  "oauth_consent",
  {
    clientId: text("client_id")
      .notNull()
      .references(() => oauthClient.clientId, { onDelete: "cascade" }),
    createdAt: timestamp("created_at").notNull(),
    id: text("id").primaryKey(),
    referenceId: text("reference_id"),
    requestedUserInfoClaims: text("requested_user_info_claims").array(),
    resources: text("resources").array(),
    scopes: text("scopes").array().notNull(),
    updatedAt: timestamp("updated_at").notNull(),
    userId: text("user_id").references(() => user.id, { onDelete: "cascade" }),
  },
  (table) => [
    index("oauth_consent_client_id_idx").on(table.clientId),
    index("oauth_consent_user_id_idx").on(table.userId),
  ]
);

export const oauthClientAssertion = privateSchema.table(
  "oauth_client_assertion",
  {
    expiresAt: timestamp("expires_at").notNull(),
    id: text("id").primaryKey(),
  }
);
